li.p:
A new set of transformations is available via ${foo@...}
parameter expansion (4.4+), e.g. to print a value with necessary
quoting:

li.pre:
# old solution
func() {
	local prev_shopt=$(shopt -p -o noglob)
	set -o noglob
	${prev_shopt}
}

# new solution
func() {
	local -
	set -o noglob
}

dd.codesample:
EAPI=8

inherit xdg-utils

IDEPEND="dev-util/desktop-file-utils"

pkg_postinst() {
	xdg_desktop_database_update
}

pkg_postrm() {
	xdg_desktop_database_update
}

pkg_postinst() {
	if ver_replacing -lt 3; then
		elog "This is a major upgrade and may break your existing setup!"
    fi
}
